package core

import (
	"github.com/jokruger/kavun/core/member"
	"github.com/jokruger/kavun/internal/text"
)

// bool's members: one function per member, each declared by the //kavun:member directive in its doc comment. The table,
// boolMethods, and the member entries of docs/reference/types/bool.md (alphabetical, so the order here is free) are
// generated by cmd/kavun-gen — run `go generate ./...` after changing a directive or a doc comment.

// Render the value per the [format mini-language](../../format_mini_language.md).
//
// ```go
// true.format()         // => "true" — default verb is t
// true.format("t")      // => "true"
// true.format("d")      // => "1"
// false.format("d")     // => "0"
// ```
//
//kavun:member format pure ([spec]) -> string
func boolFormat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return FormatWithSpec(v, id, args)
}

// Report truthiness: `false` is falsy (`!!x` ⟺ `x != bool()`).
//
// Both spellings exist on every type — the member and the universal free form:
//
// ```go
// true.is_true()        // => true
// false.is_true()       // => false
// is_true("false")      // => true — non-empty string; contrast bool("false") -> false
// is_true("")           // => false
// is_true(0)            // => false
// is_true([])           // => false
// ```
//
//kavun:member is_true pure () -> bool
func boolIsTrue(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	t, err := ValueTypes[v.Type].IsTrue(v)
	if err != nil {
		return Undefined, err
	}
	return BoolValue(t), nil
}

// Answer the receiver — a `bool` is always immutable.
//
// Identity no-ops on an immutable scalar — kept so generic code never type-errors:
//
// ```go
// true.copy()     // => true
// true.freeze()   // => true
// ```
//
//kavun:member copy pure () -> bool
func boolCopy(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	return v, nil
}

// Answer the receiver — a `bool` is always immutable; see [`copy`](#copy).
//
//kavun:member freeze pure () -> bool
func boolFreeze(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	return v, nil
}

// Answer the bool's text, `"true"` or `"false"`.
//
// ```go
// true.string()   // => "true"
// ```
//
// The `default` is taken for interface uniformity — every conversion carries it — and is never used: the
// conversion is total.
//
//kavun:member string pure ([default]) -> string
func boolString(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	s, _ := boolTypeAsString(v)
	return ConvMember(id.String(), boolTypeName, args, true, NewStringValue(s))
}

// Answer the bool's text as `runes`; see [`string`](#string).
//
// ```go
// true.runes()    // => u"true"
// ```
//
// The `default` is taken for interface uniformity — every conversion carries it — and is never used: the
// conversion is total.
//
//kavun:member runes pure ([default]) -> runes
func boolRunes(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	s, ok := v.AsString()
	return ConvMember(id.String(), boolTypeName, args, ok, NewRunesValue(text.DecodeText(s), false))
}

// Answer `1` for `true` and `0` for `false`.
//
// ```go
// true.int()      // => 1
// false.int()     // => 0
// ```
//
//kavun:member int pure ([default]) -> int
func boolInt(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	i, _ := boolTypeAsInt(v)
	return ConvMember(id.String(), boolTypeName, args, true, IntValue(i))
}

// Answer the receiver, the identity conversion.
//
// ```go
// true.bool()     // => true — identity
// ```
//
//kavun:member bool pure ([default]) -> bool
func boolBool(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return ConvMember(id.String(), boolTypeName, args, true, v)
}
